use moloch_live_runtime::{election_curve::*,value_surface::mapping_sha256};
#[path="support/value_surface_fixture.rs"]mod support;
use support::*;
fn policy()->FitPolicy{FitPolicy{factor_id:"national".into(),minimum_races:3,maximum_depth_weight:20,maximum_factor_abs:3.,minimum_residual_micros:10000}}
fn limits()->HedgeLimits{HedgeLimits{maximum_quantity_per_leg:20,maximum_gross_funding:100_000_000,maximum_absolute_factor_exposure:0,minimum_model_gain:1,tail_probability_ppm:50000,maximum_tail_loss:0}}
#[test]fn interval_loss_retains_the_full_identified_interval_not_a_midpoint_fit(){let(lo,hi,loss)=interval_factor(&[(1.,4.,1),(2.,3.,1),(0.,5.,1)],10.).unwrap();assert_eq!((lo,hi,loss),(2.,3.,0.));}
#[test]fn one_light_depth_outlier_does_not_dominate_three_nearby_intervals(){let(lo,hi,_)=interval_factor(&[(-0.1,0.1,10),(-0.2,0.2,10),(-0.1,0.1,10),(5.,6.,1)],10.).unwrap();assert!(lo>=-0.2&&hi<=0.2);assert!(interval_factor(&[(1.,0.,1)],10.).is_err());assert!(interval_factor(&[(0.,1.,0)],10.).is_err());}
#[test]fn actual_bid_ask_panel_identifies_bounded_factor_and_two_cheap_opposite_exposures(){let f=F::new();let s=f.bound(NOW).unwrap();let c=fit(&s,&policy()).unwrap();assert_eq!(c.distinct_races,5);assert!(c.factor_lower>=-0.11&&c.factor_upper<=0.11);assert!(c.residuals.iter().find(|r|r.exchange_id=="104").unwrap().buy_residual_upper_micros< -100000.);assert!(c.residuals.iter().find(|r|r.exchange_id=="105").unwrap().buy_residual_upper_micros< -100000.);let head=f.bank.durable_head();let report=f.bank.engine().report().unwrap();let ideas=hedge_candidates(&s,&c,&f.bank,&f.scope,&limits(),NOW).unwrap();assert_eq!(ideas.len(),1);let a=&ideas[0];assert_eq!(a.legs.iter().map(|l|l.quantity).collect::<Vec<_>>(),vec![20,20]);assert_eq!(a.gross_funding,14_400_000);assert_eq!(a.expected_ordinary_gain,5_600_000);assert_eq!(a.conservative_review_gain,5_400_000);assert_eq!(a.worst_ordinary_gain,5_600_000);assert_eq!(a.residual_factor_exposure,0);assert_eq!(a.exceptional_zero_payout_loss,a.gross_funding);assert!(!a.execution_authority);assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),report);}
#[test]fn actual_depth_and_full_limit_funding_bound_each_hedge(){let mut f=F::new();f.book(3,NOW,"0.350000","0.360000",2);f.book(4,NOW,"0.350000","0.360000",5);let s=f.bound(NOW).unwrap();let c=fit(&s,&policy()).unwrap();let mut p=limits();p.maximum_gross_funding=1_000_000;let a=hedge_candidates(&s,&c,&f.bank,&f.scope,&p,NOW).unwrap();assert_eq!(a.len(),1);assert_eq!(a[0].legs[0].quantity,1);assert_eq!(a[0].legs[1].quantity,1);assert_eq!(a[0].gross_funding,720000);p.maximum_gross_funding=100_000_000;let a=hedge_candidates(&s,&c,&f.bank,&f.scope,&p,NOW).unwrap();assert!(a[0].legs.iter().all(|l|l.quantity<=2));}
#[test]fn same_race_redundancy_cannot_manufacture_independent_factor_evidence(){let mut f=F::new();for m in &mut f.mappings{m.race_id="race-0".into();f.trusted_mappings.insert(mapping_sha256(m).unwrap());}let s=f.bound(NOW).unwrap();assert!(fit(&s,&policy()).is_err());}
#[test]fn changed_factor_output_or_new_native_head_cannot_reuse_frozen_hedge_inputs(){let mut f=F::new();let s=f.bound(NOW).unwrap();let mut c=fit(&s,&policy()).unwrap();c.factor_lower=1.;assert!(hedge_candidates(&s,&c,&f.bank,&f.scope,&limits(),NOW).is_err());let c=fit(&s,&policy()).unwrap();f.book(0,NOW+1,"0.490000","0.510000",20);assert!(hedge_candidates(&s,&c,&f.bank,&f.scope,&limits(),NOW+1).is_err());}
